def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            cc = (r + c) % 3

            # Get neighbors based on coord-class
            neighbors = []
            if cc == 0:  # diagonal tetrad
                for dr, dc in [(-1, 1), (-1, -1), (1, 1), (1, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(state[nr][nc])
                    else:
                        neighbors.append(1)  # OOB = 1
            elif cc == 1:  # von Neumann
                for dr, dc in [(-1, 0), (1, 0), (0, 1), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(state[nr][nc])
                    else:
                        neighbors.append(1)  # OOB = 1
            elif cc == 2:  # axial-2
                for dr, dc in [(-2, 0), (2, 0), (0, 2), (0, -2)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(state[nr][nc])
                    else:
                        neighbors.append(1)  # OOB = 1

            # Count f0, f1, f2
            f0 = neighbors.count(0)
            f1 = neighbors.count(1)
            f2 = neighbors.count(2)

            # Apply class-specific rule: majority vote
            if f0 >= f1 and f0 >= f2:
                result[r][c] = 0
            elif f1 >= f0 and f1 >= f2:
                result[r][c] = 1
            else:
                result[r][c] = 2

    return result

